from collections import deque

def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0

    n = int(lines[idx])
    m = int(lines[idx+1])
    idx += 2

    s, t = map(int, lines[idx].split())
    idx += 1

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        u, v, w = map(int, lines[idx].split())
        idx += 1
        edges.append((u, v, w, i))
        adj[u].append((v, i))
        adj[v].append((u, i))

    def is_connected(start, end, removed_edges):
        if start == end:
            return True
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            curr = queue.popleft()
            for neighbor, edge_idx in adj[curr]:
                if edge_idx not in removed_edges and neighbor not in visited:
                    visited.add(neighbor)
                    if neighbor == end:
                        return True
                    queue.append(neighbor)
        return False

    # Check if already disconnected
    if not is_connected(s, t, set()):
        return "0\n0\n"

    best_budget = float('inf')
    best_edges = []

    # Try removing 1 edge
    for edge_idx, (u, v, w, i) in enumerate(edges):
        removed = {i}
        if not is_connected(s, t, removed):
            if w < best_budget:
                best_budget = w
                best_edges = [i]

    # Try removing 2 edges
    # Optimization: only consider edges that are on at least one s-t path
    affected_edges = []
    for edge_idx, (u, v, w, i) in enumerate(edges):
        if is_connected(s, t, {i}):
            if w < best_budget:
                continue
            # If removing this edge alone doesn't disconnect s-t, it might be on a path
            # We'll check pairs
            affected_edges.append((i, w))

    if not affected_edges:
        return str(best_budget) if best_budget != float('inf') else "-1"

    # Check pairs of edges
    # First, get edges that are actually on some s-t path using flow or bridge concept
    # Simplified: check all pairs from edges with lower cost
    candidate_pairs = []
    for i, (u, v, w, e) in enumerate(edges):
        if is_connected(s, t, {e}):
            candidate_pairs.append(w)

    # For 2-edge cuts, check pairs of edges
    for i in range(len(edges)):
        if is_connected(s, t, {edges[i][3]}):
            continue

        for j in range(i + 1, len(edges)):
            removed = {edges[i][3], edges[j][3]}
            if not is_connected(s, t, removed):
                total_cost = edges[i][2] + edges[j][2]
                if total_cost < best_budget:
                    best_budget = total_cost
                    best_edges = [edges[i][3], edges[j][3]]

    # Output
    if best_budget == float('inf'):
        return "-1"

    return f"{best_budget}\n{len(best_edges)}\n{' '.join(map(str, best_edges))}\n"


