# Precompute primes up to ~32000 (sqrt of 10^9)
_precomputed_primes = []

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def get_prime_factors(num):
    """Get all prime factors of num with their exponents."""
    factors = Counter()
    if num <= 1:
        return factors

    for p in _precomputed_primes:
        if p * p > num:
            break
        while num % p == 0:
            factors[p] += 1
            num //= p
    if num > 1:
        factors[num] += 1
    return factors

# Global primes initialization
# Will be initialized lazily

def _initialize_primes():
    global _precomputed_primes
    _precomputed_primes = sieve(40000)

