        u, v = map(int, lines[2 + i].split())
        edges.append((u, v))

    # Build adjacency list for finding connected components
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components (using BFS)
    visited = [False] * (n + 1)
    components = []

    for start in range(1, n + 1):
        if not visited[start]:
            comp = []
            queue = [start]
            visited[start] = True
            while queue:
                node = queue.pop(0)
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(comp)

    # For each component and prime, count factor occurrences at even vs odd positions
    comp_prime_counts = []

    for comp in components:
        even_counts = Counter()
        odd_counts = Counter()

        for i in comp:  # i is 1-indexed position
            factors = get_prime_factors(a[i - 1])
            if i % 2 == 0:
                for prime, exponent in factors.items():
                    even_counts[prime] += exponent
            else:
                for prime, exponent in factors.items():
                    odd_counts[prime] += exponent

        # For each prime, add min(even, odd) to answer
        all_primes = set(even_counts.keys()) | set(odd_counts.keys())
        for prime in all_primes:
            comp_prime_counts.append(min(even_counts.get(prime, 0), odd_counts.get(prime, 0)))

    # Sum all contributions
    return str(sum(comp_prime_counts)) + '\n'

