        x1, y1 = p[i]
        x2, y2 = p[j]
        if y1 == y2:
            return x1
        t = (y - y1) / (y2 - y1)
        return x1 + t * (x2 - x1)

    y_coords = sorted(set(y for x, y in coords))
    y_intervals = []
    for k in range(len(y_coords) - 1):
