                    l_right, r_right = f, r
                    left_intervals.append((l_left, r_left))
                    right_intervals.append((l_right, r_right))

            # Merge left intervals and reflect
            if left_intervals:
                left_intervals.sort()
                merged_left = []
                if left_intervals:
