cache = {}

def get_f_r_prime_power(r, a):
    if a == 0:
        return 1
    if r == 0:
        return 2
    key = (r, a)
    if key in cache:
        return cache[key]

    # Compute iteratively: f_k(a) = sum_{i=0}^a f_{k-1}(i) * f_{k-1}(a-i)
    # Base: f_0(i) = 2 if i > 0, else 1

    curr = [1] + [2] * a  # f_0 for exponents 0..a

    def get_next_f(k):
        res = [0] * (a + 1)
        for i in range(a + 1):
            s = 0
            for j in range(i + 1):
                s += curr[j] * curr[i - j]
                s %= MOD
            res[i] = s
        return res

    curr = get_next_f(0)

    for _ in range(r):
        curr = get_next_f(_)
        if curr[0] > 1:
            break

    result = curr[a]
    cache[key] = result
    return result

def solve(r, n):
    result = 1
    while n > 1:
        p = spf[n]
        a = 0
        while n % p == 0:
            n //= p
            a += 1
        result = (result % MOD * get_f_r_prime_power(r, a) % MOD) % MOD
    return str(result)

