def solution(input_str):
    """
    Solve the frog game simulation problem.

    Args:
        input_str: String containing the input data

    Returns:
        String with the number of surviving frogs and their IDs
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    frogs = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        frogs.append({
            'id': i + 1,
            'pos': parts[0],
            'jump': parts[1],
            'active': True
        })

    # Simulation
    while True:
        changed = False
        for frog in range(n):
            f = frogs[frog]
            if not f['active']:
                continue

            # Calculate landing position
            from_pos = f['pos']
            jump = f['jump']
            landing = (from_pos - 1 + jump) % m + 1

            # Count frogs on path
            knocked = 0
            path_frogs = set()
            path_pos = []

            for step in range(jump):
                current = (from_pos - 1 + 1 + step) % m + 1
                path_pos.append(current)

            path_pos.append(landing)

            # Find frogs on path (must be active and distinct)
            for i in range(n):
                if i != frog and frogs[i]['active']:
                    pos = frogs[i]['pos']
                    if pos in path_pos:
                        knocked += 1

            # Remove knocked frogs
            for i in range(n):
                if i != frog and frogs[i]['active'] and frogs[i]['pos'] in path_pos:
                    frogs[i]['active'] = False
                    changed = True

            # Update jump
            f['jump'] -= knocked
            f['pos'] = landing
            if f['jump'] <= 0:
                f['active'] = False
                changed = True

        if not changed:
            break

    # Count surviving frogs
    survivors = [f['id'] for f in frogs if f['active']]
    survivors.sort()

    result = f"{len(survivors)}\n" + " ".join(map(str, survivors)) + " \n"
    return result


