def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    rev_adj = [[] for _ in range(n + 1)]
    for i in range(m):
        a, b, l = map(int, lines[1 + i].split())
        adj[a].append((b, l))
        rev_adj[b].append(a)

    q = int(lines[1 + m])
    queries = []
    idx_offset = 1 + m + 1
    for i in range(q):
        v, s, t = map(int, lines[idx_offset + i].split())
        queries.append((v, s, t))

    # Kosaraju's algorithm for SCCs

    # First pass: build finishing order using iterative DFS
    order = []
    visited = [False] * (n + 1)

    for start in range(1, n + 1):
        if not visited[start]:
            stack = [(start, 0)]
            while stack:
                v, state = stack.pop()
                if state == 0:
                    if visited[v]:
                        continue
                    visited[v] = True
                    stack.append((v, 1))
                    for to, _ in adj[v]:
                        if not visited[to]:
                            stack.append((to, 0))
                else:
                    order.append(v)

    # Second pass: find SCCs on reversed graph
    scc = [0] * (n + 1)
    scc_id = 0

    for v in reversed(order):
        if scc[v] == 0:
            scc_id += 1
            stack = [v]
            scc[v] = scc_id
            while stack:
                u = stack.pop()
                for to in rev_adj[u]:
                    if scc[to] == 0:
                        scc[to] = scc_id
                        stack.append(to)

    # Group nodes by SCC
    scc_groups = [[] for _ in range(scc_id + 1)]
    for i in range(1, n + 1):
        scc_groups[scc[i]].append(i)

    # Compute cycle GCD for each SCC
    scc_gcd = [0] * (scc_id + 1)

    for sid in range(1, scc_id + 1):
        nodes = scc_groups[sid]
        if len(nodes) <= 1:
            scc_gcd[sid] = 0
            continue

        start = nodes[0]
        dist = {start: 0}
        cycle_gcd = 0

        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v, w in adj[u]:
                if scc[v] == sid:
                    if v in dist:
                        # Found cycle through this back edge
                        cycle_len = dist[u] + w
                        cycle_gcd = gcd(cycle_gcd, cycle_len)
                    else:
                        dist[v] = dist[u] + w
                        queue.append(v)

        scc_gcd[sid] = cycle_gcd

    # Answer queries
    ans = []
    for v, s, t in queries:
        sid = scc[v]
        g = scc_gcd[sid]

        if s == 0 or g == 0 or (t - s) % g == 0:
            ans.append("YES")
        else:
            ans.append("NO")

    return '\n'.join(ans)


